@import "tailwindcss";
@import "@fontsource-variable/nunito";

/* Dark mode is class-driven so the theme toggle can override the system preference */
@custom-variant dark (&:where(.dark, .dark *));

/* Semantic tokens → Tailwind utilities (bg-surface, text-ink, border-line, …) */
@theme inline {
  --font-sans: "Nunito Variable", ui-rounded, system-ui, sans-serif;

  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-muted: var(--muted);
  --color-line: var(--line);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-soft: var(--accent-soft);
  --color-on-accent: var(--on-accent);
  --color-ok: var(--ok);
  --color-warn: var(--warn);
  --color-danger: var(--danger);
  --color-slack: var(--slack);
  --color-slack-hover: var(--slack-hover);
}

/* ---- Light (default) ---- */
:root {
  --canvas: #fbf7f2;        /* warm cream page */
  --surface: #ffffff;
  --surface-2: #f5efe8;     /* chips, inputs */
  --surface-3: #ebe3da;     /* hover */
  --ink: #1f1a2e;           /* 16.1:1 on surface */
  --ink-2: #463f57;         /* 9.6:1 on surface */
  --muted: #6b6380;         /* 5.6:1 on surface, 5.0:1 on surface-2 */
  --line: #e4dbd0;
  --accent: #7c3aed;        /* violet-600 — 5.7:1 with white text */
  --accent-hover: #6d28d9;
  --accent-soft: #ede4ff;
  --on-accent: #ffffff;
  --ok: #15803d;
  --warn: #b45309;
  --danger: #be123c;
  --slack: #611f69;         /* Slack aubergine — 11:1 with white */
  --slack-hover: #4a154b;
  --checker-a: #ffffff;
  --checker-b: #efe8df;
  --shadow: 0 1px 2px rgb(31 26 46 / 0.06), 0 8px 24px -8px rgb(31 26 46 / 0.12);
  --range-track: #d9cfc3;
  color-scheme: light;
}

/* ---- Dark ---- */
:root.dark {
  --canvas: #15121f;
  --surface: #1e1a2b;
  --surface-2: #2a2539;
  --surface-3: #363048;
  --ink: #f4f1fa;           /* 15.2:1 on surface */
  --ink-2: #d4cee3;
  --muted: #a49cba;         /* 6.3:1 on surface */
  --line: #3a3350;
  --accent: #a78bfa;        /* violet-400 — 7.4:1 against dark text */
  --accent-hover: #c4b5fd;
  --accent-soft: #2f2650;
  --on-accent: #1a1033;
  --ok: #4ade80;
  --warn: #fbbf24;
  --danger: #fb7185;
  --slack: #e0a3e8;
  --slack-hover: #ecc4f1;
  --checker-a: #2a2539;
  --checker-b: #221e31;
  --shadow: 0 1px 2px rgb(0 0 0 / 0.3), 0 12px 32px -12px rgb(0 0 0 / 0.6);
  --range-track: #463f5c;
  color-scheme: dark;
}

html, body { height: 100%; }

body {
  background-color: var(--canvas);
  color: var(--ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

/* ---- Per-tool accent hues (set on an element via data-hue) ---- */
[data-hue="sky"]     { --hue: #0ea5e9; --hue-soft: #e0f2fe; }
[data-hue="amber"]   { --hue: #f59e0b; --hue-soft: #fef3c7; }
[data-hue="emerald"] { --hue: #10b981; --hue-soft: #d1fae5; }
[data-hue="orange"]  { --hue: #f97316; --hue-soft: #ffedd5; }
[data-hue="rose"]    { --hue: #f43f5e; --hue-soft: #ffe4e6; }
[data-hue="cyan"]    { --hue: #06b6d4; --hue-soft: #cffafe; }
[data-hue="violet"]  { --hue: #8b5cf6; --hue-soft: #ede9fe; }
[data-hue="fuchsia"] { --hue: #d946ef; --hue-soft: #fae8ff; }
.dark [data-hue] { --hue-soft: color-mix(in srgb, var(--hue) 22%, var(--surface)); }

.hue-chip {
  background: var(--hue-soft);
  color: var(--hue);
}
.dark .hue-chip { color: color-mix(in srgb, var(--hue) 70%, white); }

/* ---- Tool rail buttons ---- */
.tool-btn[aria-pressed="true"] {
  background: var(--hue-soft);
  color: var(--ink);
  box-shadow: inset 0 0 0 2px var(--hue);
}
.tool-btn[aria-pressed="true"] .hue-chip {
  background: var(--hue);
  color: #fff;
}

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: 0.875rem;
  font-weight: 700;
  font-size: 0.875rem;
  line-height: 1.25rem;
  padding: 0.5rem 0.875rem;
  transition: background-color 150ms, transform 120ms, box-shadow 150ms, opacity 150ms;
  user-select: none;
}
.btn:active:not(:disabled) { transform: scale(0.96); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn-primary { background: var(--accent); color: var(--on-accent); box-shadow: 0 4px 14px -6px var(--accent); }
.btn-primary:hover:not(:disabled) { background: var(--accent-hover); }
.btn-slack { background: var(--slack); color: var(--on-accent); }
:root:not(.dark) .btn-slack { color: #fff; }
.btn-slack:hover:not(:disabled) { background: var(--slack-hover); }
.btn-soft { background: var(--surface-2); color: var(--ink); }
.btn-soft:hover:not(:disabled) { background: var(--surface-3); }
.btn-ghost { background: transparent; color: var(--ink-2); }
.btn-ghost:hover:not(:disabled) { background: var(--surface-2); color: var(--ink); }
.btn-sm { padding: 0.3rem 0.625rem; font-size: 0.8125rem; border-radius: 0.75rem; }
.btn-icon { padding: 0.5rem; }
.btn-block { width: 100%; }

/* ---- Segmented control ---- */
.segmented {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  padding: 0.25rem;
  border-radius: 0.875rem;
  background: var(--surface-2);
}
.segmented button {
  flex: 1 1 auto;
  padding: 0.3rem 0.5rem;
  border-radius: 0.625rem;
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--ink-2);
  transition: background-color 150ms, color 150ms;
}
.segmented button:hover { color: var(--ink); }
.segmented button[aria-pressed="true"] {
  background: var(--surface);
  color: var(--ink);
  box-shadow: var(--shadow);
}

/* ---- Inputs ---- */
.field-input {
  width: 100%;
  padding: 0.45rem 0.75rem;
  border-radius: 0.75rem;
  background: var(--surface-2);
  border: 2px solid transparent;
  color: var(--ink);
  font-size: 0.875rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  transition: border-color 150ms;
}
.field-input:focus { border-color: var(--accent); outline: none; }

input[type="number"] { appearance: textfield; -moz-appearance: textfield; }
input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button { opacity: 1; }

/* Range */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  background: var(--range-track);
  border-radius: 999px;
  cursor: pointer;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--surface);
  border: 4px solid var(--accent);
  box-shadow: var(--shadow);
  transition: transform 120ms;
}
input[type="range"]:active::-webkit-slider-thumb { transform: scale(1.2); }
input[type="range"]::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--surface);
  border: 4px solid var(--accent);
}

/* Checkbox / switch */
.switch {
  appearance: none;
  width: 2.25rem;
  height: 1.25rem;
  border-radius: 999px;
  background: var(--range-track);
  position: relative;
  cursor: pointer;
  transition: background-color 150ms;
  flex-shrink: 0;
}
.switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: #fff;
  transition: transform 150ms;
}
.switch:checked { background: var(--accent); }
.switch:checked::after { transform: translateX(1rem); }

/* ---- Cards & surfaces ---- */
.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 1.25rem;
  box-shadow: var(--shadow);
}

.kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.4rem;
  padding: 0.05rem 0.35rem;
  border-radius: 0.4rem;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-bottom-width: 2px;
  font-size: 0.75rem;
  font-weight: 700;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--ink-2);
}

/* Transparency checkerboard behind the GIF */
.checker {
  background-color: var(--checker-a);
  background-image:
    linear-gradient(45deg, var(--checker-b) 25%, transparent 25%),
    linear-gradient(-45deg, var(--checker-b) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--checker-b) 75%),
    linear-gradient(-45deg, transparent 75%, var(--checker-b) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
}

.pixelated { image-rendering: pixelated; }

/* Brand wordmark gradient */
.brand-gradient {
  background: linear-gradient(100deg, #8b5cf6, #ec4899 55%, #f59e0b);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* ---- Dialogs ---- */
dialog {
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 1.5rem;
  box-shadow: var(--shadow);
  padding: 0;
}
dialog::backdrop { background: rgb(15 10 30 / 0.5); backdrop-filter: blur(2px); }

/* ---- Animations ---- */
@keyframes float {
  0%, 100% { transform: translateY(0) rotate(-3deg); }
  50% { transform: translateY(-8px) rotate(3deg); }
}
@keyframes pop-in {
  from { opacity: 0; transform: translateY(8px) scale(0.96); }
  to { opacity: 1; transform: none; }
}
@keyframes indeterminate {
  from { transform: translateX(-100%); }
  to { transform: translateX(250%); }
}
@keyframes spin { to { transform: rotate(360deg); } }

.animate-float { animation: float 4s ease-in-out infinite; }
.animate-pop-in { animation: pop-in 260ms cubic-bezier(0.34, 1.56, 0.64, 1) both; }
.animate-spin { animation: spin 0.9s linear infinite; }
.progress-indeterminate { width: 40%; animation: indeterminate 1.2s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ---- Scrollbars ---- */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--line); border-radius: 999px; }
::-webkit-scrollbar-thumb:hover { background: var(--muted); }

/* ---- Focus visible (WCAG 2.4.7) ---- */
:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-radius: 0.5rem;
}
input[type="range"]:focus-visible { outline-offset: 6px; border-radius: 999px; }

/* Skip link for keyboard nav */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}
.sr-only:focus {
  position: static;
  width: auto;
  height: auto;
  padding: 0.5rem 1rem;
  margin: 0;
  overflow: visible;
  clip: auto;
  white-space: normal;
}

