const GITHUB_PATH = 'M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27s1.36.09 2 .27c1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.01 8.01 0 0 0 16 8c0-4.42-3.58-8-8-8z';

/** Render a named icon as an inline SVG string (decorative: aria-hidden) */
export function icon(name, cls = 'w-4 h-4') {
  if (name === 'github') {
    return `<svg class="${cls}" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="${GITHUB_PATH}"/></svg>`;
  }
  const node = ICONS[name];
  if (!node) throw new Error(`Unknown icon: ${name}`);
  const children = node
    .map(([tag, attrs]) => `<${tag} ${Object.entries(attrs).map(([k, v]) => `${k}="${v}"`).join(' ')}/>`)
    .join('');
  return `<svg class="${cls} shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${children}</svg>`;
}

/** Replace every `<i data-icon="name" class="…">` placeholder under root with its SVG */
export function hydrateIcons(root = document) {
  for (const el of root.querySelectorAll('i[data-icon]')) {
    el.outerHTML = icon(el.dataset.icon, el.className || 'w-4 h-4');
  }
}

/** Small HTML-string helpers shared by tool panels, so every panel looks the same */
import { icon } from './icons.js';

export function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/** Header at the top of a tool panel: colored icon chip, title, one-line hint */
export function panelHeader({ title, iconName, hue, hint }) {
  return `
    <div class="flex items-start gap-3 mb-4" data-hue="${hue}">
      <span class="hue-chip w-10 h-10 rounded-2xl flex items-center justify-center">${icon(iconName, 'w-5 h-5')}</span>
      <div class="min-w-0">
        <h2 class="text-lg font-extrabold leading-tight">${title}</h2>
        ${hint ? `<p class="text-sm text-muted leading-snug">${hint}</p>` : ''}
      </div>
    </div>`;
}

export function button({ id = '', label, iconName = '', variant = 'soft', size = '', block = false, attrs = '' }) {
  const cls = ['btn', `btn-${variant}`, size && `btn-${size}`, block && 'btn-block'].filter(Boolean).join(' ');
  return `<button ${id ? `id="${id}"` : ''} type="button" class="${cls}" ${attrs}>${iconName ? icon(iconName) : ''}<span>${label}</span></button>`;
}

/** Labelled range slider with a live value readout (`<output id="{id}-val">`) */
export function sliderField({ id, label, min, max, step = 1, value, display }) {
  return `
    <div>
      <div class="flex items-baseline justify-between mb-1.5">
        <label for="${id}" class="text-sm font-bold text-ink-2">${label}</label>
        <output id="${id}-val" for="${id}" class="text-sm font-extrabold tabular-nums">${display ?? value}</output>
      </div>
      <input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" />
    </div>`;
}

export function numberField({ id, label, value, min = '', max = '', step = 1, suffix = '' }) {
  return `
    <div class="min-w-0">
      <label for="${id}" class="text-xs font-bold text-muted block mb-1">${label}</label>
      <div class="relative">
        <input id="${id}" type="number" inputmode="decimal" value="${value}" min="${min}" max="${max}" step="${step}" class="field-input ${suffix ? 'pr-8' : ''}" />
        ${suffix ? `<span class="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-bold text-muted pointer-events-none">${suffix}</span>` : ''}
      </div>
    </div>`;
}

/**
 * Segmented control. options: [{value, label}]. Clicks are handled by bindSegmented.
 */
export function segmented({ id, label = '', options, value = null }) {
  return `
    <div>
      ${label ? `<p class="text-sm font-bold text-ink-2 mb-1.5" id="${id}-label">${label}</p>` : ''}
      <div id="${id}" class="segmented" role="group" ${label ? `aria-labelledby="${id}-label"` : ''}>
        ${options.map((o) => `<button type="button" data-value="${o.value}" aria-pressed="${String(o.value) === String(value)}">${o.label}</button>`).join('')}
      </div>
    </div>`;
}

/** Wire a segmented control; returns a setter to change the highlighted value programmatically */
export function bindSegmented(id, onChange) {
  const group = document.getElementById(id);
  const set = (value) => {
    for (const b of group.querySelectorAll('button')) {
      b.setAttribute('aria-pressed', String(b.dataset.value === String(value)));
    }
  };
  group.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-value]');
    if (!btn) return;
    set(btn.dataset.value);
    onChange(btn.dataset.value);
  });
  return set;
}

/** Bind a slider to its <output> readout; returns the input element */
export function bindSlider(id, format = (v) => v, onInput = () => {}) {
  const input = document.getElementById(id);
  const out = document.getElementById(`${id}-val`);
  const update = () => {
    out.textContent = format(parseFloat(input.value));
    onInput(parseFloat(input.value));
  };
  input.addEventListener('input', update);
  input.sync = () => { out.textContent = format(parseFloat(input.value)); };
  return input;
}

/** Small explanatory note (e.g. "preview is approximate") */
export function note(text, iconName = 'info') {
  return `<p class="flex items-start gap-1.5 text-xs text-muted">${icon(iconName, 'w-3.5 h-3.5 mt-0.5')}<span>${text}</span></p>`;
}

/** Lightweight pub/sub state store with snapshot-based undo/redo history */
import { parseGifInfo } from './gif-info.js';

const MAX_HISTORY_ENTRIES = 30;
const MAX_HISTORY_BYTES = 256 * 1024 * 1024; // 256 MB of GIF snapshots

const initialState = {
  /** @type {'landing'|'editor'|'batch'} which screen is showing */
  view: 'landing',
  /** @type {Uint8Array|null} current GIF bytes (= history.entries[history.index].gif) */
  currentGif: null,
  /** GIF metadata for currentGif */
  meta: { width: 0, height: 0, frames: 0, duration: 0, delays: [], size: 0 },
  /** @type {string|null} original filename of the loaded GIF */
  fileName: null,
  /**
   * Snapshot history. Entry 0 is always the original upload.
   * @type {{entries: Array<{label: string, gif: Uint8Array, meta: object}>, index: number}}
   */
  history: { entries: [], index: -1 },
  /** @type {string|null} currently active tool */
  activeTool: null,
  /** whether an FFmpeg job is running */
  processing: false,
  /** FFmpeg engine status, shown as a header pill */
  engine: { status: 'idle', pct: 0, text: '' },
};

let state = structuredClone(initialState);
const listeners = new Map();

export function getState() {
  return state;
}

export function setState(partial) {
  const prev = { ...state };
  Object.assign(state, partial);

  for (const [key, cbs] of listeners) {
    if (key in partial) {
      for (const cb of cbs) cb(state[key], prev[key]);
    }
  }
}

export function subscribe(key, cb) {
  if (!listeners.has(key)) listeners.set(key, new Set());
  listeners.get(key).add(cb);
  return () => listeners.get(key).delete(cb);
}

// ---- History ----

function showEntry(history) {
  const entry = history.entries[history.index];
  setState({ history, currentGif: entry.gif, meta: entry.meta });
}

/** Start a fresh editing session with a newly loaded GIF */
export function loadGif(gif, fileName) {
  const meta = parseGifInfo(gif);
  setState({ fileName });
  showEntry({ entries: [{ label: 'Original', gif, meta }], index: 0 });
  return meta;
}

/** Record an edit result as the new current state (drops any redo branch) */
export function commit(label, gif) {
  const { history } = state;
  const entries = history.entries.slice(0, history.index + 1);
  entries.push({ label, gif, meta: parseGifInfo(gif) });

  // Evict the oldest edits (never the original) to stay within budget
  let bytes = entries.reduce((sum, e) => sum + e.gif.byteLength, 0);
  while (entries.length > 2 && (entries.length > MAX_HISTORY_ENTRIES || bytes > MAX_HISTORY_BYTES)) {
    const [evicted] = entries.splice(1, 1);
    bytes -= evicted.gif.byteLength;
    console.log(`[History] Evicted "${evicted.label}" to stay within budget`);
  }

  showEntry({ entries, index: entries.length - 1 });
}

export function canUndo() {
  return state.history.index > 0;
}

export function canRedo() {
  return state.history.index < state.history.entries.length - 1;
}

/** Jump to a history entry; returns its label, or null if out of range */
export function jumpTo(index) {
  const { history } = state;
  if (index < 0 || index >= history.entries.length || index === history.index) return null;
  showEntry({ ...history, index });
  return history.entries[index].label;
}

export function undo() {
  const label = state.history.entries[state.history.index]?.label;
  return canUndo() && jumpTo(state.history.index - 1) !== null ? label : null;
}

export function redo() {
  return canRedo() ? jumpTo(state.history.index + 1) : null;
}

export function getOriginal() {
  return state.history.entries[0] ?? null;
}

export function resetState() {
  const { engine } = state;
  setState({ ...structuredClone(initialState), engine });
}

