  const reader = response.body.getReader();
  const chunks = [];
  let received = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    received += value.length;
    if (contentLength > 0) {
      // Download is the bulk of the work: map it onto 5–90%
      const pct = 5 + Math.round((received / contentLength) * 85);
