import { icon } from '../ui/icons.js';

const STYLES = {
  success: { iconName: 'check', chip: 'bg-ok text-surface' },
  error: { iconName: 'warn', chip: 'bg-danger text-surface' },
  info: { iconName: 'info', chip: 'bg-accent text-on-accent' },
};

const MAX_TOASTS = 3;

export function showToast(message, type = 'info', duration = 3500) {
  const container = document.getElementById('toast-container');
  const style = STYLES[type] || STYLES.info;

  const el = document.createElement('div');
  el.className = 'card pointer-events-auto w-full flex items-center gap-3 pl-2.5 pr-1.5 py-2 text-sm font-bold animate-pop-in';
  el.setAttribute('role', type === 'error' ? 'alert' : 'status');
  el.innerHTML = `
    <span class="w-7 h-7 rounded-full flex items-center justify-center shrink-0 ${style.chip}">${icon(style.iconName, 'w-4 h-4')}</span>
    <span class="flex-1 min-w-0"></span>
    <button type="button" class="btn btn-ghost btn-icon !p-1.5" aria-label="Dismiss">${icon('x', 'w-3.5 h-3.5')}</button>`;
  el.querySelector('span.flex-1').textContent = message;

  const dismiss = () => {
    if (!el.isConnected) return;
    el.style.transition = 'opacity 200ms, transform 200ms';
    el.style.opacity = '0';
    el.style.transform = 'translateY(6px)';
    setTimeout(() => el.remove(), 200);
  };
  el.querySelector('button').addEventListener('click', dismiss);

  container.appendChild(el);
  while (container.children.length > MAX_TOASTS) container.firstElementChild.remove();

  setTimeout(dismiss, duration);
}

/**
 * Stage player: frame-accurate GIF playback on a canvas via WebCodecs ImageDecoder,
 * with zoom, before/after compare and live-preview hooks (rate, reverse, loop range, CSS filter).
 * Falls back to a plain animated <img> where ImageDecoder is unavailable.
 */
import { subscribe, getState, getOriginal } from '../utils/state.js';
import { icon } from '../ui/icons.js';

/** Decoded frames are cached as ImageBitmaps when they fit in this budget */
const FRAME_CACHE_BUDGET = 192 * 1024 * 1024;
const ZOOM_STEPS = [0.25, 0.5, 1, 2, 3, 4, 6, 8];
const MAX_FIT_UPSCALE = 3;

const hasImageDecoder = typeof window.ImageDecoder !== 'undefined';

let canvas, ctx, img, wrap, viewport, comparePane, compareImg;
let gen = 0;             // load generation; stale async work checks this
let decoder = null;
let bitmaps = [];        // ImageBitmap|undefined per frame (cache)
let cacheable = false;
let decoded = false;     // canvas mode active for current GIF
let count = 0;
let delays = [];
let index = 0;
let playing = true;
let rate = 1;
let reverse = false;
let range = null;        // [start, endExclusive] loop range, or null for all frames
let timer = null;
let zoom = 'fit';
let scale = 1;
let comparing = false;
let imgUrl = null;
let compareUrl = null;
const listeners = { frame: new Set(), layout: new Set() };

function emit(type) {
  for (const cb of listeners[type]) cb();
}

/** Subscribe to 'frame' (index/playing changed) or 'layout' (size/zoom changed) */
export function on(type, cb) {
  listeners[type].add(cb);
  return () => listeners[type].delete(cb);
}

export function initPlayer() {
  canvas = document.getElementById('player-canvas');
  ctx = canvas.getContext('2d');
  img = document.getElementById('preview-img');
  wrap = document.getElementById('media-wrap');
  viewport = document.getElementById('viewport');
  comparePane = document.getElementById('compare-pane');
  compareImg = document.getElementById('compare-img');

  subscribe('currentGif', (gif) => {
    if (gif) load(gif, getState().meta);
    else unload();
  });

  new ResizeObserver(() => layout()).observe(viewport);

  // Controls
  document.getElementById('pc-play').addEventListener('click', togglePlay);
  document.getElementById('pc-prev').addEventListener('click', () => step(-1));
  document.getElementById('pc-next').addEventListener('click', () => step(1));
  const scrub = document.getElementById('pc-scrub');
  scrub.addEventListener('input', () => { pause(); seek(parseInt(scrub.value, 10)); });
  document.getElementById('zoom-in').addEventListener('click', zoomIn);
  document.getElementById('zoom-out').addEventListener('click', zoomOut);
  document.getElementById('zoom-label').addEventListener('click', toggleZoom);
  document.getElementById('compare-btn').addEventListener('click', toggleCompare);

  on('frame', renderControls);
}

// ---- Loading ----

function unload() {
  gen++;
  stopTimer();
  closeDecoder();
  if (imgUrl) URL.revokeObjectURL(imgUrl);
  imgUrl = null;
  img.removeAttribute('src');
  setCompare(false);
  zoom = 'fit';
  range = null;
  rate = 1;
  reverse = false;
  setPreviewFilter('');
}

function closeDecoder() {
  for (const b of bitmaps) b?.close();
  bitmaps = [];
  decoder?.close();
  decoder = null;
  decoded = false;
}

async function load(gif, meta) {
  const myGen = ++gen;
  stopTimer();
  closeDecoder();
  index = 0;
  range = null;

  // Always keep an <img> URL around: used by the fallback and filter-preset swatches
  if (imgUrl) URL.revokeObjectURL(imgUrl);
  imgUrl = URL.createObjectURL(new Blob([gif], { type: 'image/gif' }));

  canvas.width = meta.width;
  canvas.height = meta.height;
  layout();

  if (hasImageDecoder) {
    try {
      decoder = new ImageDecoder({ data: gif, type: 'image/gif' });
      await decoder.tracks.ready;
      await decoder.completed;
      if (myGen !== gen) return;
      count = decoder.tracks.selectedTrack.frameCount;
      delays = Array.from({ length: count }, (_, i) => normalizeDelay(meta.delays?.[i]));
      cacheable = meta.width * meta.height * 4 * count <= FRAME_CACHE_BUDGET;
      decoded = true;
      canvas.classList.remove('hidden');
      img.classList.add('hidden');
      document.getElementById('player-controls').classList.remove('invisible');
      await drawFrame(0);
      if (playing) startTimer();
      emit('frame');
      if (cacheable) cacheAllFrames(myGen);
      return;
    } catch (err) {
      console.warn('[Player] ImageDecoder failed, falling back to <img>:', err);
      closeDecoder();
      if (myGen !== gen) return;
    }
  }

  // Fallback: native animated <img>, no frame controls
  count = meta.frames;
  delays = (meta.delays || []).map(normalizeDelay);
  img.src = imgUrl;
  img.classList.remove('hidden');
  canvas.classList.add('hidden');
  document.getElementById('player-controls').classList.add('invisible');
  emit('frame');
}

/** Browsers render GIF delays of ≤10ms as 100ms; mirror that so previews match */
function normalizeDelay(ms) {
  return !ms || ms <= 10 ? 100 : ms;
}

async function cacheAllFrames(myGen) {
  for (let i = 0; i < count; i++) {
    if (myGen !== gen) return;
    if (bitmaps[i]) continue;
    const { image } = await decoder.decode({ frameIndex: i });
    if (myGen !== gen) { image.close(); return; }
    bitmaps[i] = await createImageBitmap(image);
    image.close();
  }
  console.log(`[Player] Cached ${count} decoded frames`);
  emit('frame');
}

async function drawFrame(i) {
  const myGen = gen;
  if (bitmaps[i]) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(bitmaps[i], 0, 0);
    return;
  }
  const { image } = await decoder.decode({ frameIndex: i });
  if (myGen === gen) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(image, 0, 0);
  }
  image.close();
}

// ---- Playback ----

function stopTimer() {
  clearTimeout(timer);
  timer = null;
}

function bounds() {
  return range ?? [0, count];
}

function nextIndex(i, dir) {
  const [start, end] = bounds();
  let n = i + dir;
  if (n >= end) n = start;
  if (n < start) n = end - 1;
  return n;
}

function startTimer() {
  stopTimer();
  const myGen = gen;
  const tick = () => {
    timer = setTimeout(async () => {
      if (myGen !== gen || !playing) return;
      index = nextIndex(index, reverse ? -1 : 1);
      await drawFrame(index);
      if (myGen !== gen || !playing) return;
      emit('frame');
      tick();
    }, delays[index] / rate);
  };
  tick();
}

export function play() {
  if (!decoded) return;
  playing = true;
  startTimer();
  emit('frame');
}

export function pause() {
  playing = false;
  stopTimer();
  emit('frame');
}

export function togglePlay() {
  if (playing) pause();
  else play();
}

export async function seek(i) {
  if (!decoded) return;
  const [start, end] = bounds();
  index = Math.max(start, Math.min(end - 1, i));
  await drawFrame(index);
  emit('frame');
  if (playing) startTimer();
}

export function step(dir) {
  if (!decoded) return;
  pause();
  seek(nextIndex(index, dir));
}

// ---- Live-preview hooks used by tools ----

export function setRate(r) {
  rate = r;
}

/** Reverse playback needs random access, so only offered when frames are cached */
export function canReverse() {
  return decoded && cacheable;
}

export function setReverse(on) {
  reverse = on && canReverse();
}

/** Loop only frames [start, endExclusive); pass null to clear */
export function setLoopRange(r) {
  range = r && decoded ? [Math.max(0, r[0]), Math.min(count, r[1])] : null;
  if (range && (index < range[0] || index >= range[1])) seek(range[0]);
}

export function setPreviewFilter(css) {
  canvas.style.filter = css;
  img.style.filter = css;
}

export function isFrameAccurate() {
  return decoded;
}

export function getFrameInfo() {
  return { index, count, delays, playing };
}

/** The <img> URL of the current GIF (for swatch thumbnails) */
export function getImageUrl() {
  return imgUrl;
}

/** Cached bitmap for a frame, or null if not decoded yet */
export function getBitmap(i) {
  return bitmaps[i] ?? null;
}

/** The element the GIF is displayed in, for mapping overlay coordinates */
export function getMediaWrap() {
  return wrap;
}

export function getScale() {
  return scale;
}

// ---- Zoom & layout ----

function fitScale(pane, w, h) {
  const pad = 24;
  const s = Math.min((pane.clientWidth - pad) / w, (pane.clientHeight - pad) / h);
  return Math.max(0.05, Math.min(s, MAX_FIT_UPSCALE));
}

function layout() {
  const { meta } = getState();
  if (!meta?.width) return;

  scale = zoom === 'fit' ? fitScale(viewport, meta.width, meta.height) : zoom;
  wrap.style.width = `${Math.round(meta.width * scale)}px`;
  wrap.style.height = `${Math.round(meta.height * scale)}px`;
  const pixelated = scale > 1;
  canvas.classList.toggle('pixelated', pixelated);
  img.classList.toggle('pixelated', pixelated);

  if (comparing) {
    const orig = getOriginal().meta;
    const s = fitScale(comparePane, orig.width, orig.height);
    compareImg.style.width = `${Math.round(orig.width * s)}px`;
    compareImg.style.height = `${Math.round(orig.height * s)}px`;
  }

  document.getElementById('zoom-label').textContent = zoom === 'fit' ? 'Fit' : `${Math.round(scale * 100)}%`;
  emit('layout');
}

function setZoom(z) {
  zoom = z;
  layout();
}

export function zoomIn() {
  const next = ZOOM_STEPS.find((z) => z > scale + 0.001);
  if (next) setZoom(next);
}

export function zoomOut() {
  const prev = [...ZOOM_STEPS].reverse().find((z) => z < scale - 0.001);
  if (prev) setZoom(prev);
}

/** Toggle between "fit to stage" and actual pixels */
export function toggleZoom() {
  setZoom(zoom === 'fit' ? 1 : 'fit');
}

// ---- Compare ----

export function isComparing() {
  return comparing;
}

export function toggleCompare() {
  setCompare(!comparing);
}

function setCompare(on) {
  const stage = document.getElementById('stage');
  const btn = document.getElementById('compare-btn');
  comparing = on && getOriginal() !== null;

  if (compareUrl) URL.revokeObjectURL(compareUrl);
  compareUrl = null;
  if (comparing) {
    compareUrl = URL.createObjectURL(new Blob([getOriginal().gif], { type: 'image/gif' }));
    compareImg.src = compareUrl;
  } else {
    compareImg.removeAttribute('src');
  }

  comparePane.classList.toggle('hidden', !comparing);
  document.getElementById('edited-badge').classList.toggle('hidden', !comparing);
  // Side by side on wide stages, stacked on narrow ones
  stage.classList.toggle('md:grid-cols-2', comparing);
  stage.classList.toggle('max-md:grid-rows-2', comparing);
  btn.setAttribute('aria-pressed', String(comparing));
  btn.classList.toggle('btn-soft', comparing);
  btn.classList.toggle('btn-ghost', !comparing);
  requestAnimationFrame(layout);
}

// ---- Controls UI ----

function renderControls() {
  const playBtn = document.getElementById('pc-play');
  playBtn.innerHTML = icon(playing ? 'pause' : 'play', 'w-4 h-4');
  playBtn.setAttribute('aria-label', playing ? 'Pause' : 'Play');

  const scrub = document.getElementById('pc-scrub');
  scrub.max = String(Math.max(0, count - 1));
  scrub.value = String(index);
  document.getElementById('pc-frame').textContent = count ? `${index + 1} / ${count}` : '';
}

import { getState, setState, subscribe, commit } from '../utils/state.js';
import { writeFile, readFile, runFFmpeg, deleteFile, initFFmpeg, onProgress } from '../ffmpeg/engine.js';
import { showToast } from '../components/toast.js';

let jobText = '';

function setJobProgress(ratio, sub = '') {
  const bar = document.getElementById('job-bar');
  const valid = Number.isFinite(ratio) && ratio > 0 && ratio <= 1;
  bar.classList.toggle('progress-indeterminate', !valid);
  bar.style.width = valid ? `${Math.round(ratio * 100)}%` : '';
  document.getElementById('job-sub').textContent = sub;
}

export function showProcessing(text = 'Working…') {
  console.log(`[Processing] Start: ${text}`);
  jobText = text;
  setState({ processing: true });
  document.getElementById('job-overlay').classList.remove('hidden');
  document.getElementById('job-text').textContent = text;
  setJobProgress(null);
}

export function hideProcessing() {
  console.log('[Processing] Done');
  setState({ processing: false });
  onProgress(null);
  document.getElementById('job-overlay').classList.add('hidden');
}

/** While a job waits on the engine, mirror the engine's download progress in the overlay */
export function initJobOverlay() {
  subscribe('engine', (engine) => {
    if (!getState().processing) return;
    if (engine.status === 'loading') {
      document.getElementById('job-text').textContent = 'Warming up the engine…';
      setJobProgress(engine.pct / 100, engine.text);
    } else if (engine.status === 'ready') {
      document.getElementById('job-text').textContent = jobText;
      setJobProgress(null);
    }
  });
}

/**
 * Run an async FFmpeg job behind the stage overlay. Errors become a toast.
 * Returns the job's result, or undefined if it failed or another job was running.
 */
export async function runJob(text, fn) {
  if (getState().processing) return undefined;
  showProcessing(text);
  try {
    await initFFmpeg();
    document.getElementById('job-text').textContent = text;
    return await fn();
  } catch (err) {
    console.error(`[Job] ${text} failed:`, err);
    showToast(`${text.replace(/…$/, '')} failed: ${err?.message || err}`, 'error', 6000);
    return undefined;
  } finally {
    hideProcessing();
  }
}

/**
 * Write `gif` as input.gif, run each FFmpeg pass, and return output.gif's bytes.
 * Two-pass commands (palettegen → paletteuse) write palette.png in between.
 */
export async function transformGif(gif, passes) {
  await writeFile('input.gif', gif);
  try {
    for (let i = 0; i < passes.length; i++) {
      onProgress((p) => setJobProgress(
        (i + Math.min(1, Math.max(0, p))) / passes.length,
        passes.length > 1 ? `Pass ${i + 1} of ${passes.length}` : '',
      ));
      await runFFmpeg(passes[i]);
    }
    return await readFile('output.gif');
  } finally {
    onProgress(null);
    await deleteFile('input.gif');
    await deleteFile('output.gif');
    await deleteFile('palette.png');
  }
}

/**
 * The common tool flow: transform the current GIF, commit it to history, toast.
 * `passes` is an array of FFmpeg arg arrays reading input.gif → output.gif.
 */
export function applyEdit({ label, busy, passes, success }) {
  return runJob(busy, async () => {
    const before = getState().currentGif;
    const result = await transformGif(before, passes);
    commit(label, result);
    showToast(success ? success(result, before) : `${label} applied`, 'success');
    return result;
  });
}

import { setState, getState, subscribe } from '../utils/state.js';
import { icon } from '../ui/icons.js';
import { renderIdlePanel } from './history.js';

/**
 * @typedef {object} Tool
 * @property {string} id
 * @property {string} label
 * @property {string} iconName
 * @property {string} hue        accent hue name (see [data-hue] in custom.css)
 * @property {string} hint       one-line description shown in the panel header
 * @property {(panel: HTMLElement) => void} render  build the options panel
 * @property {() => void} [exit] tear down live previews / overlays when leaving the tool
 */

/** @type {Tool[]} */
const tools = [];

/** Tools self-register on import; rail order = registration order, hotkey = position */
export function registerTool(tool) {
  tools.push(tool);
}

export function getTools() {
  return tools;
}

export function initToolbar() {
  const rail = document.getElementById('tool-rail');
  rail.innerHTML = tools.map((tool, i) => `
    <button type="button" data-tool="${tool.id}" data-hue="${tool.hue}" aria-pressed="false"
      aria-keyshortcuts="${i + 1}" title="${tool.label} (${i + 1})"
      class="tool-btn shrink-0 flex flex-col items-center gap-1 px-2 py-2 rounded-2xl text-xs font-bold text-ink-2 hover:bg-surface-2 transition-colors min-w-16 lg:w-full">
      <span class="hue-chip w-9 h-9 rounded-xl flex items-center justify-center transition-colors">${icon(tool.iconName, 'w-5 h-5')}</span>
      <span>${tool.label}</span>
    </button>`).join('');

  rail.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-tool]');
    if (btn) selectTool(btn.dataset.tool);
  });

  document.getElementById('panel-close').addEventListener('click', () => selectTool(null));

  subscribe('activeTool', updateActiveState);
  // Edits, undo and redo change the GIF under the tool: rebuild its panel from the new state
  subscribe('currentGif', (gif) => {
    if (gif && getState().view === 'editor') renderPanel();
  });
  renderPanel();
}

function getTool(id) {
  return tools.find((t) => t.id === id) ?? null;
}

/** Select a tool by id (toggles off if already active); null closes the current tool */
export function selectTool(toolId) {
  if (getState().processing) return;
  const current = getState().activeTool;
  const next = current === toolId ? null : toolId;
  getTool(current)?.exit?.();
  setState({ activeTool: next });
  renderPanel();
}

/** Select by 1-based rail position (keyboard shortcut) */
export function selectToolByIndex(i) {
  if (tools[i]) selectTool(tools[i].id);
}

function renderPanel() {
  const panel = document.getElementById('tool-options');
  const tool = getTool(getState().activeTool);
  if (tool) {
    tool.exit?.();
    panel.innerHTML = '';
    tool.render(panel);
  } else {
    renderIdlePanel(panel);
  }
}

function updateActiveState(activeId) {
  for (const btn of document.querySelectorAll('#tool-rail [data-tool]')) {
    btn.setAttribute('aria-pressed', String(btn.dataset.tool === activeId));
  }
  // Mobile: the options panel is a bottom sheet that only opens with a tool
  const panel = document.getElementById('panel');
  panel.classList.toggle('max-lg:hidden', !activeId);
  document.getElementById('panel-close').classList.toggle('hidden', !activeId);
}

import { getState, subscribe, undo, redo, jumpTo, canUndo, canRedo } from '../utils/state.js';
import { formatSize } from '../utils/file-utils.js';
import { escapeHtml } from '../ui/components.js';
import { icon } from '../ui/icons.js';
import { showToast } from './toast.js';

export function initHistory() {
  document.getElementById('undo-btn').addEventListener('click', handleUndo);
  document.getElementById('redo-btn').addEventListener('click', handleRedo);
  document.getElementById('history-list').addEventListener('click', (e) => {
    const item = e.target.closest('[data-entry]');
    if (item && !getState().processing) jumpTo(Number(item.dataset.entry));
  });
  subscribe('history', render);
  subscribe('processing', render);
}

export function handleUndo() {
  if (getState().processing) return;
  const label = undo();
  showToast(label ? `Undid “${label}”` : 'Nothing to undo', 'info', 2000);
}

export function handleRedo() {
  if (getState().processing) return;
  const label = redo();
  showToast(label ? `Redid “${label}”` : 'Nothing to redo', 'info', 2000);
}

function render() {
  const { history, processing } = getState();
  document.getElementById('undo-btn').disabled = processing || !canUndo();
  document.getElementById('redo-btn').disabled = processing || !canRedo();

  const edits = history.entries.length - 1;
  document.getElementById('history-count').textContent = edits > 0 ? `${edits} edit${edits === 1 ? '' : 's'}` : '';

  document.getElementById('history-list').innerHTML = history.entries.map((entry, i) => {
    const current = i === history.index;
    const future = i > history.index;
    return `
      <li>
        <button type="button" data-entry="${i}" ${current ? 'aria-current="step"' : ''}
          class="w-full flex items-center gap-2 px-2.5 py-1.5 rounded-xl text-left text-sm transition-colors
            ${current ? 'bg-accent-soft font-extrabold' : 'hover:bg-surface-2 font-semibold'} ${future ? 'opacity-50' : ''}">
          <span class="w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-black shrink-0
            ${current ? 'bg-accent text-on-accent' : 'bg-surface-2 text-muted'}">${i === 0 ? '★' : i}</span>
          <span class="flex-1 truncate">${escapeHtml(entry.label)}</span>
          <span class="text-xs text-muted tabular-nums">${formatSize(entry.gif.byteLength)}</span>
        </button>
      </li>`;
  }).join('');
}

/** Panel content when no tool is selected: a friendly nudge plus quick tips */
export function renderIdlePanel(panel) {
  const { meta } = getState();
  const isSquare = meta.width === meta.height;
  panel.innerHTML = `
    <div class="text-center py-4">
      <div class="text-4xl mb-2" aria-hidden="true">👈</div>
      <h2 class="text-lg font-extrabold">Pick a tool to start</h2>
      <p class="text-sm text-muted mb-4">Or press <kbd class="kbd">1</kbd>–<kbd class="kbd">8</kbd> to jump straight to one.</p>
    </div>
    <ul class="space-y-2 text-sm">
      <li class="flex gap-2.5 items-start p-3 rounded-2xl bg-surface-2">
        ${icon('slack', 'w-4 h-4 mt-0.5 text-slack')}
        <span><strong>Slack emoji</strong> crops to a square and squeezes the GIF under 128 KB.
        ${meta.size <= 128 * 1024 && isSquare ? 'This one already fits! 🎉' : ''}</span>
      </li>
      <li class="flex gap-2.5 items-start p-3 rounded-2xl bg-surface-2">
        ${icon('compare', 'w-4 h-4 mt-0.5 text-accent')}
        <span><strong>Compare</strong> shows your edit next to the original. Press <kbd class="kbd">\\</kbd> to toggle.</span>
      </li>
      <li class="flex gap-2.5 items-start p-3 rounded-2xl bg-surface-2">
        ${icon('history', 'w-4 h-4 mt-0.5 text-accent')}
        <span>Every edit is saved in <strong>History</strong>. Click any step to jump back to it.</span>
      </li>
    </ul>`;
}

import { subscribe, getOriginal } from '../utils/state.js';
import { formatSize } from '../utils/file-utils.js';
import { icon } from '../ui/icons.js';

const SLACK_MAX_SIZE = 128 * 1024;

const chip = (content, cls = 'bg-surface-2 text-ink-2', attrs = '') =>
  `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full ${cls}" ${attrs}>${content}</span>`;

/** Metadata bar under the stage: dimensions, frames, duration, fps, size delta, Slack fit */
export function initPreview() {
  subscribe('meta', (meta) => {
    const bar = document.getElementById('metadata-bar');
    if (!meta?.width) { bar.innerHTML = ''; return; }

    const seconds = meta.duration / 1000;
    const fps = seconds > 0 ? (meta.frames / seconds).toFixed(1) : '0';
    const original = getOriginal();

    let size = formatSize(meta.size);
    if (original && original.meta.size !== meta.size) {
      const pct = Math.round((meta.size / original.meta.size - 1) * 100);
      const tone = pct <= 0 ? 'text-ok' : 'text-warn';
      size = `${formatSize(original.meta.size)} → ${size} <span class="${tone}">(${pct > 0 ? '+' : ''}${pct}%)</span>`;
    }

    const slackFits = meta.size <= SLACK_MAX_SIZE && meta.width === meta.height;
    const slack = slackFits
      ? chip(`${icon('check', 'w-3 h-3')} Slack-ready`, 'bg-ok/15 text-ok')
      : chip(`${icon('slack', 'w-3 h-3')} ${meta.size > SLACK_MAX_SIZE ? `${formatSize(meta.size - SLACK_MAX_SIZE)} over Slack limit` : 'Not square for Slack'}`,
        'bg-surface-2 text-muted', 'title="Slack emoji: square, ≤128 KB. Use the Slack emoji button to fix automatically."');

    bar.innerHTML = [
      chip(`${meta.width} × ${meta.height}`, undefined, 'title="Dimensions"'),
      chip(`${meta.frames} frames`),
      chip(`${seconds.toFixed(2)}s`, undefined, 'title="Duration"'),
      chip(`${fps} fps`),
      chip(size, undefined, 'title="File size"'),
      slack,
    ].join('');
  });
}

import { getState, commit } from '../utils/state.js';
import { showToast } from './toast.js';
import { downloadBlob, formatSize } from '../utils/file-utils.js';
import { slackEmojiExport } from '../tools/slack-emoji.js';
import { runJob } from '../tools/shared.js';

const SLACK_MAX_SIZE = 128 * 1024;

export function initExportPanel() {
  document.getElementById('export-download').addEventListener('click', handleDownload);
  document.getElementById('export-slack').addEventListener('click', handleSlackExport);
}

/** "cat.gif" → "cat-edited.gif" (or the original name when nothing was edited) */
function downloadName(suffix) {
  const { fileName, history } = getState();
  const base = (fileName || 'animation.gif').replace(/\.gif$/i, '');
  return history.index === 0 && !suffix ? `${base}.gif` : `${base}-${suffix || 'edited'}.gif`;
}

export function handleDownload() {
  const { currentGif, processing } = getState();
  if (!currentGif || processing) return;
  const name = downloadName();
  downloadBlob(currentGif, name);
  showToast(`Downloaded ${name}`, 'success');
}

async function handleSlackExport() {
  const { currentGif, fileName } = getState();
  if (!currentGif) return;

  const result = await runJob('Squeezing into a Slack emoji…', () => slackEmojiExport(currentGif));
  if (!result) return;

  // Keep the result in history so it can be undone or tweaked further
  commit('Slack emoji', result);
  const { meta } = getState();
  downloadBlob(result, fileName || 'slack-emoji.gif');

  const size = formatSize(result.byteLength);
  if (result.byteLength <= SLACK_MAX_SIZE) {
    showToast(`Slack emoji ready! ${meta.width}×${meta.height}, ${size}`, 'success');
  } else {
    showToast(`Best we could do is ${size} (Slack wants ≤128 KB). Downloaded anyway. Try trimming it first.`, 'error', 7000);
  }
}

