import { getState, loadGif, setState } from '../utils/state.js';
import { readFileAsArrayBuffer } from '../utils/file-utils.js';
import { initFFmpeg } from '../ffmpeg/engine.js';
import { confirmDialog } from '../ui/dialog.js';
import { showView } from '../ui/views.js';
import { showToast } from './toast.js';
import { filterGifs, openBatch, addToBatch } from './batch.js';

/** File intake: landing drop target, full-window drag-and-drop, and paste */
export function initDropzone() {
  const dropzone = document.getElementById('dropzone');
  const fileInput = document.getElementById('file-input');

  const browse = (multiple) => {
    fileInput.multiple = multiple;
    fileInput.click();
  };
  dropzone.addEventListener('click', () => browse(true));
  dropzone.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      browse(true);
    }
  });
  document.getElementById('landing-edit').addEventListener('click', () => browse(false));
  document.getElementById('landing-batch').addEventListener('click', () => browse(true));

  fileInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
    fileInput.value = '';
  });

  initWindowDrop();

  window.addEventListener('paste', (e) => {
    if (e.target.closest?.('input, textarea')) return;
    const files = e.clipboardData?.files;
    if (files?.length) {
      e.preventDefault();
      handleFiles(files);
    }
  });
}

/** Dropping files anywhere in the window shows an overlay and loads them */
function initWindowDrop() {
  const overlay = document.getElementById('drop-overlay');
  let depth = 0;
  const hasFiles = (e) => Array.from(e.dataTransfer?.types || []).includes('Files');

  window.addEventListener('dragenter', (e) => {
    if (!hasFiles(e) || getState().processing) return;
    e.preventDefault();
    if (depth++ === 0) {
      document.getElementById('drop-overlay-hint').textContent = getState().view === 'batch'
        ? 'Drop GIFs to add them to the batch'
        : 'Drop one GIF to edit it, or several for Slack emoji';
      overlay.classList.remove('hidden');
    }
  });
  window.addEventListener('dragleave', (e) => {
    if (!hasFiles(e)) return;
    if (--depth <= 0) {
      depth = 0;
      overlay.classList.add('hidden');
    }
  });
  window.addEventListener('dragover', (e) => {
    if (hasFiles(e)) e.preventDefault();
  });
  window.addEventListener('drop', (e) => {
    if (!hasFiles(e)) return;
    e.preventDefault();
    depth = 0;
    overlay.classList.add('hidden');
    if (!getState().processing) handleFiles(e.dataTransfer.files);
  });
}

/** One GIF opens the editor; several go to the batch Slack export view */
export async function handleFiles(fileList) {
  const gifs = filterGifs(fileList);
  if (gifs.length === 0) return;

  const { view, history } = getState();
  if (view === 'batch') {
    addToBatch(gifs);
    return;
  }
  if (view === 'editor' && history.entries.length > 1) {
    const ok = await confirmDialog({
      title: 'Replace this GIF?',
      body: `You'll lose your ${history.entries.length - 1} edit(s). Download first if you want to keep them.`,
      confirmLabel: 'Replace',
    });
    if (!ok) return;
  }

  if (gifs.length === 1) openEditor(gifs[0]);
  else openBatch(gifs);
}

async function openEditor(file) {
  console.log(`[Dropzone] File received: ${file.name} (${(file.size / 1024).toFixed(1)} KB)`);
  const data = await readFileAsArrayBuffer(file);
  setState({ activeTool: null });
  showView('editor');
  const meta = loadGif(data, file.name);
  console.log('[Dropzone] GIF parsed:', meta);

  // Warm the engine up in the background so the first edit is quick
  initFFmpeg().catch(() => {});

  showToast(`Loaded ${file.name}: ${meta.width}×${meta.height}, ${meta.frames} frames`, 'success');
}

import { zipSync } from 'fflate';
import { parseGifInfo } from '../utils/gif-info.js';
import { readFileAsArrayBuffer, downloadBlob, formatSize } from '../utils/file-utils.js';
import { resetState } from '../utils/state.js';
import { slackEmojiExport } from '../tools/slack-emoji.js';
import { escapeHtml } from '../ui/components.js';
import { icon } from '../ui/icons.js';
import { showView } from '../ui/views.js';
import { showToast } from './toast.js';

const SLACK_MAX_SIZE = 128 * 1024; // 128 KB

/** @type {Array<{id: number, name: string, data: Uint8Array, meta: object, previewUrl: string, result: Uint8Array|null, resultUrl: string|null, status: 'pending'|'working'|'ok'|'over'|'failed'}>} */
let items = [];
let nextId = 1;
let exporting = false;

export function initBatch() {
  const input = document.getElementById('batch-file-input');

  document.getElementById('batch-add-btn').addEventListener('click', () => input.click());
  document.getElementById('batch-clear-btn').addEventListener('click', () => clearBatch());
  document.getElementById('batch-export-btn').addEventListener('click', exportAll);

  input.addEventListener('change', (e) => {
    addToBatch(filterGifs(e.target.files));
    input.value = '';
  });

  document.getElementById('batch-grid').addEventListener('click', (e) => {
    const remove = e.target.closest('[data-remove]');
    if (remove) removeItem(Number(remove.dataset.remove));
    const download = e.target.closest('[data-download]');
    if (download) downloadItem(Number(download.dataset.download));
  });
}

/** Keep only GIFs from a FileList, toasting about anything rejected */
export function filterGifs(fileList) {
  const files = Array.from(fileList || []);
  const gifs = files.filter((f) => f.type === 'image/gif');
  const rejected = files.length - gifs.length;
  if (rejected > 0) {
    console.warn(`[Batch] Rejected ${rejected} non-GIF file(s)`);
    showToast(`Skipped ${rejected} non-GIF file${rejected === 1 ? '' : 's'}. Only GIFs are supported.`, 'error');
  }
  return gifs;
}

export async function openBatch(files) {
  resetState();
  showView('batch');
  await addToBatch(files);
}

export async function addToBatch(files) {
  if (files.length === 0 || exporting) return;
  console.log(`[Batch] Adding ${files.length} GIF(s)`);

  for (const file of files) {
    const data = await readFileAsArrayBuffer(file);
    items.push({
      id: nextId++,
      name: uniqueName(file.name),
      data,
      meta: parseGifInfo(data),
      previewUrl: URL.createObjectURL(new Blob([data], { type: 'image/gif' })),
      result: null,
      resultUrl: null,
      status: 'pending',
    });
  }

  render();
  showToast(`Added ${files.length} GIF${files.length === 1 ? '' : 's'}`, 'success');
}

/** Avoid collisions inside the zip: "cat.gif", "cat-2.gif", "cat-3.gif"… */
function uniqueName(name) {
  const taken = new Set(items.map((i) => i.name.toLowerCase()));
  if (!taken.has(name.toLowerCase())) return name;

  const dot = name.lastIndexOf('.');
  const base = dot > 0 ? name.slice(0, dot) : name;
  const ext = dot > 0 ? name.slice(dot) : '';
  let n = 2;
  while (taken.has(`${base}-${n}${ext}`.toLowerCase())) n++;
  return `${base}-${n}${ext}`;
}

function revoke(item) {
  URL.revokeObjectURL(item.previewUrl);
  if (item.resultUrl) URL.revokeObjectURL(item.resultUrl);
}

function removeItem(id) {
  if (exporting) return;
  const item = items.find((i) => i.id === id);
  if (!item) return;
  revoke(item);
  items = items.filter((i) => i.id !== id);
  if (items.length === 0) clearBatch();
  else render();
}

function downloadItem(id) {
  const item = items.find((i) => i.id === id);
  if (item?.result) downloadBlob(item.result, item.name);
}

/** Empty the batch and return to the landing page */
export function clearBatch() {
  if (exporting) return;
  for (const item of items) revoke(item);
  items = [];
  render();
  showView('landing');
  console.log('[Batch] Cleared, back to landing');
}

export function hasBatchItems() {
  return items.length > 0;
}

function statusPill(item) {
  const pill = (cls, content) => `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-extrabold ${cls}">${content}</span>`;
  const delta = item.result ? Math.round((item.result.byteLength / item.meta.size - 1) * 100) : 0;
  switch (item.status) {
    case 'working': return pill('bg-accent-soft text-accent', `${icon('loader', 'w-3 h-3 animate-spin')} Squeezing…`);
    case 'ok': return pill('bg-ok/15 text-ok', `${icon('check', 'w-3 h-3')} ${formatSize(item.result.byteLength)} (${delta}%)`);
    case 'over': return pill('bg-warn/15 text-warn', `${icon('warn', 'w-3 h-3')} ${formatSize(item.result.byteLength)}, over 128 KB`);
    case 'failed': return pill('bg-danger/15 text-danger', `${icon('error', 'w-3 h-3')} Failed`);
    default: return pill('bg-surface-2 text-muted', 'Ready');
  }
}

function render() {
  const done = items.filter((i) => i.result).length;
  document.getElementById('batch-count').textContent =
    `${items.length} GIF${items.length === 1 ? '' : 's'}${done ? ` · ${done} optimized` : ''}`;

  const pending = items.filter((i) => !i.result).length;
  document.getElementById('batch-export-label').textContent = exporting
    ? 'Exporting…'
    : pending === 0 && items.length > 0 ? 'Download .zip' : 'Export all (.zip)';
  for (const id of ['batch-export-btn', 'batch-add-btn', 'batch-clear-btn']) {
    document.getElementById(id).disabled = exporting || (id === 'batch-export-btn' && items.length === 0);
  }

  document.getElementById('batch-grid').innerHTML = items.map((item) => `
    <div class="card p-2 flex flex-col gap-2 relative animate-pop-in">
      <button type="button" data-remove="${item.id}" ${exporting ? 'disabled' : ''}
        class="absolute top-3 right-3 z-10 w-7 h-7 rounded-full bg-surface/90 shadow flex items-center justify-center hover:bg-danger hover:text-surface transition-colors disabled:opacity-0"
        aria-label="Remove ${escapeHtml(item.name)}">${icon('x', 'w-3.5 h-3.5')}</button>
      <div class="aspect-square rounded-xl overflow-hidden checker flex items-center justify-center">
        <img src="${item.resultUrl || item.previewUrl}" alt="" class="max-w-full max-h-full object-contain ${item.status === 'working' ? 'opacity-50' : ''}" />
      </div>
      <div class="px-1 min-w-0">
        <p class="text-sm font-extrabold truncate" title="${escapeHtml(item.name)}">${escapeHtml(item.name)}</p>
        <p class="text-xs text-muted font-semibold">${item.meta.width}×${item.meta.height} · ${formatSize(item.meta.size)}</p>
      </div>
      <div class="px-1 pb-1 flex items-center gap-1 min-h-7">
        ${statusPill(item)}
        ${item.result ? `<button type="button" data-download="${item.id}" class="ml-auto btn btn-ghost btn-icon !p-1" aria-label="Download ${escapeHtml(item.name)}" title="Download this one">${icon('download', 'w-4 h-4')}</button>` : ''}
      </div>
    </div>
  `).join('');
}

function setProgress(done, total) {
  const wrap = document.getElementById('batch-progress');
  const pct = total ? Math.round((done / total) * 100) : 0;
  wrap.classList.toggle('hidden', !exporting);
  wrap.setAttribute('aria-valuenow', String(pct));
  document.getElementById('batch-progress-bar').style.width = `${pct}%`;
}

/** Optimize every GIF that isn't done yet, then download all results as one zip */
async function exportAll() {
  if (items.length === 0 || exporting) return;
  const todo = items.filter((i) => !i.result);
  console.log(`[Batch] Exporting ${items.length} GIF(s) for Slack (${todo.length} to optimize)`);

  exporting = true;
  try {
    for (let i = 0; i < todo.length; i++) {
      const item = todo[i];
      item.status = 'working';
      setProgress(i, todo.length);
      render();
      try {
        item.result = await slackEmojiExport(item.data);
        item.resultUrl = URL.createObjectURL(new Blob([item.result], { type: 'image/gif' }));
        item.status = item.result.byteLength <= SLACK_MAX_SIZE ? 'ok' : 'over';
      } catch (err) {
        console.error(`[Batch] Failed to export ${item.name}:`, err);
        item.result = null;
        item.status = 'failed';
      }
    }
    setProgress(todo.length, todo.length);
  } finally {
    exporting = false;
    setProgress(0, 0);
    render();
  }

  const files = Object.fromEntries(items.filter((i) => i.result).map((i) => [i.name, i.result]));
  const exported = Object.keys(files).length;
  if (exported === 0) {
    showToast('Slack export failed for every GIF', 'error');
    return;
  }

  // GIFs are already compressed, so store without deflate
  const zip = zipSync(files, { level: 0 });
  downloadBlob(zip, 'slack-emojis.zip', 'application/zip');

  const over = items.filter((i) => i.status === 'over').length;
  const failed = items.filter((i) => i.status === 'failed').length;
  const parts = [`Exported ${exported} GIF${exported === 1 ? '' : 's'}`];
  if (over) parts.push(`${over} over 128 KB`);
  if (failed) parts.push(`${failed} failed`);
  showToast(parts.join(' · '), over || failed ? 'error' : 'success', 6000);
}

import { getState } from '../utils/state.js';
import { getTools, selectToolByIndex, selectTool } from './toolbar.js';
import { handleUndo, handleRedo } from './history.js';
import { handleDownload } from './export-panel.js';
import * as player from './player.js';

const isMac = /Mac|iPhone|iPad/.test(navigator.platform);
const MOD = isMac ? '⌘' : 'Ctrl';

function shortcutList() {
  return [
    ['Open a tool', ['1', '–', String(getTools().length)]],
    ['Close the tool', ['Esc']],
    ['Play / pause', ['Space']],
    ['Previous / next frame', [',', '.']],
    ['Zoom in / out', ['+', '−']],
    ['Fit / actual size', ['0']],
    ['Compare with original', ['\\']],
    ['Undo', [MOD, 'Z']],
    ['Redo', [MOD, '⇧', 'Z']],
    ['Download', [MOD, 'S']],
    ['Paste a GIF', [MOD, 'V']],
    ['Show shortcuts', ['?']],
  ];
}

export function openShortcuts() {
  const list = document.getElementById('shortcuts-list');
  list.innerHTML = shortcutList().map(([label, keys]) => `
    <dt class="text-ink-2 font-semibold">${label}</dt>
    <dd class="flex items-center gap-1 justify-end">${keys.map((k) => (k === '–' ? '<span class="text-muted">–</span>' : `<kbd class="kbd">${k}</kbd>`)).join('')}</dd>
  `).join('');
  document.getElementById('shortcuts-dialog').showModal();
}

function isTyping(target) {
  return target instanceof HTMLElement &&
    (target.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName));
}

export function initShortcuts() {
  document.getElementById('shortcuts-btn').addEventListener('click', openShortcuts);

  document.addEventListener('keydown', (e) => {
    if (document.querySelector('dialog[open]')) return;
    const { view } = getState();
    const mod = e.metaKey || e.ctrlKey;
    const key = e.key;

    if (key === '?' && !isTyping(e.target)) {
      e.preventDefault();
      openShortcuts();
      return;
    }
    if (view !== 'editor') return;

    // Modifier shortcuts work everywhere except inside text fields (where ⌘Z is native undo)
    if (mod && !e.altKey) {
      const k = key.toLowerCase();
      if (k === 'z' && !isTyping(e.target)) {
        e.preventDefault();
        if (e.shiftKey) handleRedo();
        else handleUndo();
      } else if (k === 'y' && !isMac && !isTyping(e.target)) {
        e.preventDefault();
        handleRedo();
      } else if (k === 's') {
        e.preventDefault();
        handleDownload();
      }
      return;
    }

    if (e.altKey || isTyping(e.target)) return;
    // Let focused buttons/sliders keep Space/Enter/arrows
    const onControl = e.target instanceof HTMLElement && e.target.closest('button, [role="button"], a');

    if (/^[1-9]$/.test(key)) {
      selectToolByIndex(Number(key) - 1);
    } else if (key === 'Escape') {
      if (getState().activeTool) selectTool(null);
    } else if (key === ' ' && !onControl) {
      e.preventDefault();
      player.togglePlay();
    } else if (key === ',') {
      player.step(-1);
    } else if (key === '.') {
      player.step(1);
    } else if (key === '+' || key === '=') {
      player.zoomIn();
    } else if (key === '-' || key === '_') {
      player.zoomOut();
    } else if (key === '0') {
      player.toggleZoom();
    } else if (key === '\\') {
      player.toggleCompare();
    }
  });
}

import './styles/custom.css';

// Components
import { initDropzone } from './components/dropzone.js';
import { initPreview } from './components/preview.js';
import { initPlayer } from './components/player.js';
import { initToolbar, closeTool } from './components/toolbar.js';
import { initExportPanel } from './components/export-panel.js';
import { initBatch, clearBatch, hasBatchItems } from './components/batch.js';
import { initHistory } from './components/history.js';
import { initShortcuts } from './components/shortcuts.js';

// Tools (self-registering via registerTool; rail order = import order)
import './tools/resize.js';
import './tools/crop.js';
import './tools/trim.js';
import './tools/speed.js';
import './tools/reverse.js';
import './tools/frames.js';
import './tools/filters.js';
import './tools/compress.js';

import { getState, subscribe, resetState } from './utils/state.js';
import { initFFmpeg } from './ffmpeg/engine.js';
import { initJobOverlay } from './tools/shared.js';
import { icon, hydrateIcons } from './ui/icons.js';
import { confirmDialog } from './ui/dialog.js';
import { showView } from './ui/views.js';

// ---- Theme: light → dark → system ----
const THEME_KEY = 'gif-editor-theme';
const THEMES = ['light', 'dark', 'system'];
const THEME_ICONS = { light: 'sun', dark: 'moon', system: 'system' };
const systemDark = matchMedia('(prefers-color-scheme: dark)');

function readTheme() {
  try {
    const saved = localStorage.getItem(THEME_KEY);
    return THEMES.includes(saved) ? saved : 'system';
  } catch {
    return 'system';
  }
}

function applyTheme(pref) {
  const dark = pref === 'dark' || (pref === 'system' && systemDark.matches);
  document.documentElement.classList.toggle('dark', dark);
  const btn = document.getElementById('theme-toggle');
  const next = THEMES[(THEMES.indexOf(pref) + 1) % THEMES.length];
  btn.innerHTML = icon(THEME_ICONS[pref], 'w-5 h-5');
  btn.setAttribute('aria-label', `Theme: ${pref}. Switch to ${next}`);
  btn.title = `Theme: ${pref}`;
}

function initThemeToggle() {
  let pref = readTheme();
  applyTheme(pref);
  systemDark.addEventListener('change', () => applyTheme(pref));

  document.getElementById('theme-toggle').addEventListener('click', () => {
    pref = THEMES[(THEMES.indexOf(pref) + 1) % THEMES.length];
    try { localStorage.setItem(THEME_KEY, pref); } catch { /* private mode */ }
    applyTheme(pref);
    console.log(`[App] Theme set to ${pref}`);
  });
}

// ---- Engine status pill ----
let pillTimer = null;

function initEnginePill() {
  const pill = document.getElementById('engine-pill');
  const show = (visible) => {
    pill.classList.toggle('hidden', !visible);
    pill.classList.toggle('flex', visible);
  };

  subscribe('engine', (engine) => {
    clearTimeout(pillTimer);
    const iconEl = document.getElementById('engine-pill-icon');
    const retry = document.getElementById('engine-retry');
    retry.classList.toggle('hidden', engine.status !== 'error');
    pill.classList.toggle('text-danger', engine.status === 'error');

    if (engine.status === 'loading') {
      iconEl.innerHTML = icon('loader', 'w-4 h-4 animate-spin text-accent');
      document.getElementById('engine-pill-text').textContent = `Warming up engine · ${Math.round(engine.pct)}%`;
      pill.title = engine.text;
      show(true);
    } else if (engine.status === 'ready') {
      iconEl.innerHTML = icon('check', 'w-4 h-4 text-ok');
      document.getElementById('engine-pill-text').textContent = 'Engine ready';
      pillTimer = setTimeout(() => show(false), 1500);
    } else if (engine.status === 'error') {
      iconEl.innerHTML = icon('warn', 'w-4 h-4');
      document.getElementById('engine-pill-text').textContent = "Engine couldn't load";
      show(true);
    }
  });

  document.getElementById('engine-retry').addEventListener('click', () => initFFmpeg().catch(() => {}));
}

// ---- Home ----
async function goHome() {
  const { view, history } = getState();
  if (view === 'editor' && history.entries.length > 1) {
    const ok = await confirmDialog({
      title: 'Leave this GIF?',
      body: `You'll lose your ${history.entries.length - 1} edit(s). Download first if you want to keep them.`,
      confirmLabel: 'Leave',
    });
    if (!ok) return;
  }
  if (view === 'batch' && hasBatchItems()) {
    clearBatch();
    return;
  }
  closeTool();
  resetState();
  showView('landing');
}

// ---- Browser check ----
function checkBrowser() {
  const ua = navigator.userAgent;
  const isChromium = /Chrome|Chromium|Edg|OPR|Brave/i.test(ua) && !/Safari/i.test(ua.replace(/Chrome|Chromium|Edg|OPR|Brave/gi, ''));
  const isFirefox = /Firefox/i.test(ua);
  const isChrome = /Chrome/i.test(ua) && !/Edg/i.test(ua);
  const isEdge = /Edg/i.test(ua);

  if (isChrome || isEdge || isChromium || isFirefox) return true;

  // Fallback: check for Chrome or Firefox-like features
  if (/Chrome\/\d/i.test(ua) || /Firefox\/\d/i.test(ua)) return true;

  return false;
}

function bootstrap() {
  console.log('[App] Bootstrapping GIF Editor…');
  hydrateIcons();
  initThemeToggle();

  if (!checkBrowser()) {
    console.warn('[App] Unsupported browser detected, blocking usage');
    document.getElementById('unsupported-banner').classList.remove('hidden');
    return;
  }
  console.log('[App] Browser check passed');

  initPlayer();
  initPreview();
  initToolbar();
  initHistory();
  initExportPanel();
  initBatch();
  initDropzone();
  initShortcuts();
  initJobOverlay();
  initEnginePill();
  subscribe('fileName', (name) => { document.getElementById('file-name').textContent = name ?? ''; });
  document.getElementById('home-btn').addEventListener('click', goHome);
  console.log('[App] All components initialized');
}

bootstrap();

import { getState } from '../utils/state.js';
import { resizeCmd } from '../ffmpeg/commands.js';
import { showToast } from '../components/toast.js';
import { formatSize } from '../utils/file-utils.js';
import { registerTool } from '../components/toolbar.js';
import { applyEdit } from './shared.js';
import { panelHeader, numberField, segmented, bindSegmented, button, note } from '../ui/components.js';
import { icon } from '../ui/icons.js';

const tool = {
  id: 'resize',
  label: 'Resize',
  iconName: 'resize',
  hue: 'sky',
  hint: 'Make it bigger or smaller.',
  render: renderResize,
};
registerTool(tool);

const PRESETS = [
  { value: '0.25', label: '25%' },
  { value: '0.5', label: '50%' },
  { value: '0.75', label: '75%' },
  { value: '2', label: '200%' },
  { value: 'fit128', label: 'Fit 128' },
];

let locked = true;

function renderResize(panel) {
  const { meta } = getState();
  const aspectRatio = meta.width / meta.height;

  panel.innerHTML = `
    ${panelHeader(tool)}
    <div class="space-y-4">
      <div class="flex gap-2 items-end">
        ${numberField({ id: 'resize-w', label: 'Width', value: meta.width, min: 1, max: 4096, suffix: 'px' })}
        <button id="resize-lock" type="button" class="btn btn-soft btn-icon mb-0.5 shrink-0" aria-pressed="${locked}"></button>
        ${numberField({ id: 'resize-h', label: 'Height', value: meta.height, min: 1, max: 4096, suffix: 'px' })}
      </div>
      ${segmented({ id: 'resize-presets', label: 'Quick sizes', options: PRESETS })}
      <p id="resize-summary" class="text-sm text-ink-2"></p>
      ${button({ id: 'resize-apply', label: 'Apply resize', iconName: 'check', variant: 'primary', block: true })}
      ${note('Fit 128 makes the longest side 128px, which suits Slack emoji.')}
    </div>
  `;

  const wInput = document.getElementById('resize-w');
  const hInput = document.getElementById('resize-h');
  const lockBtn = document.getElementById('resize-lock');

  const renderLock = () => {
    lockBtn.innerHTML = icon(locked ? 'lock' : 'unlock', 'w-4 h-4');
    lockBtn.setAttribute('aria-pressed', String(locked));
    lockBtn.setAttribute('aria-label', locked ? 'Aspect ratio locked' : 'Aspect ratio unlocked');
    lockBtn.title = locked ? 'Aspect ratio locked' : 'Aspect ratio unlocked';
    lockBtn.classList.toggle('btn-primary', locked);
    lockBtn.classList.toggle('btn-soft', !locked);
  };
  const summarize = () => {
    const w = parseInt(wInput.value, 10) || 0;
    const pct = Math.round((w / meta.width) * 100);
    document.getElementById('resize-summary').innerHTML =
      `<strong>${meta.width}×${meta.height}</strong> → <strong>${w}×${parseInt(hInput.value, 10) || 0}</strong> <span class="text-muted">(${pct}%)</span>`;
  };
  renderLock();
  summarize();

  const setPreset = bindSegmented('resize-presets', (value) => {
    const scale = value === 'fit128' ? 128 / Math.max(meta.width, meta.height) : parseFloat(value);
    wInput.value = Math.max(1, Math.round(meta.width * scale));
    hInput.value = Math.max(1, Math.round(meta.height * scale));
    summarize();
  });

  lockBtn.addEventListener('click', () => {
    locked = !locked;
    renderLock();
  });
  wInput.addEventListener('input', () => {
    if (locked) hInput.value = Math.max(1, Math.round(parseInt(wInput.value, 10) / aspectRatio)) || '';
    setPreset(null);
    summarize();
  });
  hInput.addEventListener('input', () => {
    if (locked) wInput.value = Math.max(1, Math.round(parseInt(hInput.value, 10) * aspectRatio)) || '';
    setPreset(null);
    summarize();
  });

  document.getElementById('resize-apply').addEventListener('click', () => {
    const w = parseInt(wInput.value, 10);
    const h = parseInt(hInput.value, 10);
    if (!w || !h || w < 1 || h < 1 || w > 4096 || h > 4096) { showToast('Pick a size between 1 and 4096 px', 'error'); return; }
    if (w === meta.width && h === meta.height) { showToast("That's already the current size", 'info'); return; }

    applyEdit({
      label: `Resize to ${w}×${h}`,
      busy: 'Resizing…',
      passes: [resizeCmd('input.gif', 'output.gif', w, h)],
      success: (result) => `Resized to ${w}×${h} (${formatSize(result.byteLength)})`,
    });
  });
}

import { getState } from '../utils/state.js';
import { cropCmd } from '../ffmpeg/commands.js';
import { showToast } from '../components/toast.js';
import { formatSize } from '../utils/file-utils.js';
import { registerTool } from '../components/toolbar.js';
import { applyEdit } from './shared.js';
import * as player from '../components/player.js';
import { panelHeader, numberField, segmented, bindSegmented, button, note } from '../ui/components.js';

const tool = {
  id: 'crop',
  label: 'Crop',
  iconName: 'crop',
  hue: 'amber',
  hint: 'Cut away the edges you don’t need.',
  render: renderCrop,
  exit: exitCrop,
};
registerTool(tool);

const RATIOS = [
  { value: 'free', label: 'Free' },
  { value: '1', label: '1:1' },
  { value: '1.3333', label: '4:3' },
  { value: '1.7778', label: '16:9' },
  { value: '0.5625', label: '9:16' },
];

/** Overlay canvas extends this far (CSS px) beyond the GIF so edge handles stay grabbable */
const PAD = 12;
const HANDLE_HIT = 14;

let rect = { x: 0, y: 0, w: 0, h: 0 };
let ratio = null;       // locked aspect ratio (w/h) or null for free
let cleanup = null;     // tears down listeners on exit

function renderCrop(panel) {
  const { meta } = getState();
  rect = { x: 0, y: 0, w: meta.width, h: meta.height };
  ratio = null;

  panel.innerHTML = `
    ${panelHeader(tool)}
    <div class="space-y-4">
      ${segmented({ id: 'crop-ratio', label: 'Aspect ratio', options: RATIOS, value: 'free' })}
      <div class="grid grid-cols-2 gap-2">
        ${numberField({ id: 'crop-x', label: 'X', value: 0, min: 0, suffix: 'px' })}
        ${numberField({ id: 'crop-y', label: 'Y', value: 0, min: 0, suffix: 'px' })}
        ${numberField({ id: 'crop-w', label: 'Width', value: meta.width, min: 1, suffix: 'px' })}
        ${numberField({ id: 'crop-h', label: 'Height', value: meta.height, min: 1, suffix: 'px' })}
      </div>
      <div class="flex gap-2">
        ${button({ id: 'crop-reset', label: 'Reset', variant: 'soft' })}
        <div class="flex-1">${button({ id: 'crop-apply', label: 'Apply crop', iconName: 'check', variant: 'primary', block: true })}</div>
      </div>
      ${note('Drag on the GIF to draw a box. Drag inside it to move it, or drag the handles to resize.')}
    </div>
  `;

  bindSegmented('crop-ratio', (value) => {
    ratio = value === 'free' ? null : parseFloat(value);
    if (ratio) {
      // Largest centered box with this ratio
      let w = meta.width;
      let h = w / ratio;
      if (h > meta.height) { h = meta.height; w = h * ratio; }
      setRect({ x: (meta.width - w) / 2, y: (meta.height - h) / 2, w, h });
    }
  });

  for (const id of ['crop-x', 'crop-y', 'crop-w', 'crop-h']) {
    document.getElementById(id).addEventListener('input', () => {
      const v = (k) => parseInt(document.getElementById(`crop-${k}`).value, 10) || 0;
      rect = clampRect({ x: v('x'), y: v('y'), w: v('w'), h: v('h') });
      draw();
    });
  }

  document.getElementById('crop-reset').addEventListener('click', () => {
    setRect({ x: 0, y: 0, w: meta.width, h: meta.height });
  });

  document.getElementById('crop-apply').addEventListener('click', () => {
    const { x, y, w, h } = rect;
    if (w < 1 || h < 1) { showToast('Draw a crop box first', 'error'); return; }
    if (w === meta.width && h === meta.height) { showToast('The crop box covers the whole GIF. Shrink it first.', 'info'); return; }
    applyEdit({
      label: `Crop to ${w}×${h}`,
      busy: 'Cropping…',
      passes: [cropCmd('input.gif', 'output.gif', w, h, x, y)],
      success: (result) => `Cropped to ${w}×${h} (${formatSize(result.byteLength)})`,
    });
  });

  enterCrop();
}

function exitCrop() {
  cleanup?.();
  cleanup = null;
  document.getElementById('crop-canvas').classList.add('hidden');
}

// ---- Geometry ----

function clampRect({ x, y, w, h }) {
  const { meta } = getState();
  x = Math.max(0, Math.min(meta.width - 1, Math.round(x)));
  y = Math.max(0, Math.min(meta.height - 1, Math.round(y)));
  w = Math.max(1, Math.min(meta.width - x, Math.round(w)));
  h = Math.max(1, Math.min(meta.height - y, Math.round(h)));
  return { x, y, w, h };
}

function setRect(r) {
  rect = clampRect(r);
  for (const k of ['x', 'y', 'w', 'h']) document.getElementById(`crop-${k}`).value = rect[k];
  draw();
}

/**
 * Resize `start` by dragging edges named in `mode` (any of n/s/e/w) by (dx, dy) GIF px,
 * keeping the opposite edges anchored and honoring the locked ratio.
 */
function resizeRect(start, mode, dx, dy) {
  const { meta } = getState();
  let left = start.x, top = start.y;
  let right = start.x + start.w, bottom = start.y + start.h;
  if (mode.includes('w')) left = Math.min(right - 1, Math.max(0, left + dx));
  if (mode.includes('e')) right = Math.max(left + 1, Math.min(meta.width, right + dx));
  if (mode.includes('n')) top = Math.min(bottom - 1, Math.max(0, top + dy));
  if (mode.includes('s')) bottom = Math.max(top + 1, Math.min(meta.height, bottom + dy));
  let w = right - left;
  let h = bottom - top;

  if (ratio) {
    if (mode === 'n' || mode === 's') w = h * ratio;
    else if (mode === 'e' || mode === 'w') h = w / ratio;
    else if (w / h > ratio) w = h * ratio;
    else h = w / ratio;

    const maxW = mode.includes('w') ? right : meta.width - left;
    const maxH = mode.includes('n') ? bottom : meta.height - top;
    w = Math.min(w, maxW, maxH * ratio);
    h = w / ratio;
    if (mode.includes('w')) left = right - w;
    if (mode.includes('n')) top = bottom - h;
  }
  return { x: left, y: top, w, h };
}

// ---- Overlay interaction ----

function enterCrop() {
  exitCrop();
  const canvas = document.getElementById('crop-canvas');
  canvas.classList.remove('hidden');
  const controller = new AbortController();
  const { signal } = controller;

  /** CSS px (relative to canvas) → GIF px */
  const toGif = (cx, cy) => {
    const s = player.getScale();
    return { gx: (cx - PAD) / s, gy: (cy - PAD) / s };
  };
  const local = (e) => {
    const r = canvas.getBoundingClientRect();
    return { cx: e.clientX - r.left, cy: e.clientY - r.top };
  };

  const hitTest = (cx, cy) => {
    const s = player.getScale();
    const l = PAD + rect.x * s, t = PAD + rect.y * s;
    const r = l + rect.w * s, b = t + rect.h * s;
    const near = (a, v) => Math.abs(a - v) < HANDLE_HIT;
    const inX = cx > l - HANDLE_HIT && cx < r + HANDLE_HIT;
    const inY = cy > t - HANDLE_HIT && cy < b + HANDLE_HIT;
    let mode = '';
    if (inX && near(cy, t)) mode += 'n';
    else if (inX && near(cy, b)) mode += 's';
    if (inY && near(cx, l)) mode += 'w';
    else if (inY && near(cx, r)) mode += 'e';
    if (mode) return mode;
    if (cx > l && cx < r && cy > t && cy < b) return 'move';
    return 'draw';
  };

  const CURSORS = { n: 'ns-resize', s: 'ns-resize', e: 'ew-resize', w: 'ew-resize', nw: 'nwse-resize', se: 'nwse-resize', ne: 'nesw-resize', sw: 'nesw-resize', move: 'move', draw: 'crosshair' };

  let drag = null;
  canvas.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    const { cx, cy } = local(e);
    const { gx, gy } = toGif(cx, cy);
    drag = { mode: hitTest(cx, cy), cx, cy, gx, gy, start: { ...rect } };
    canvas.setPointerCapture(e.pointerId);
    if (drag.mode === 'move') canvas.style.cursor = 'grabbing';
  }, { signal });

  canvas.addEventListener('pointermove', (e) => {
    const { cx, cy } = local(e);
    if (!drag) {
      canvas.style.cursor = CURSORS[hitTest(cx, cy)];
      return;
    }
    const s = player.getScale();
    const dx = (cx - drag.cx) / s;
    const dy = (cy - drag.cy) / s;
    const { meta } = getState();

    if (drag.mode === 'move') {
      setRect({
        ...drag.start,
        x: Math.max(0, Math.min(meta.width - drag.start.w, drag.start.x + dx)),
        y: Math.max(0, Math.min(meta.height - drag.start.h, drag.start.y + dy)),
      });
    } else if (drag.mode === 'draw') {
      if (Math.abs(dx) < 2 && Math.abs(dy) < 2) return;
      // Drawing = resizing a zero-size box anchored at the press point
      const anchor = { x: Math.max(0, Math.min(meta.width, drag.gx)), y: Math.max(0, Math.min(meta.height, drag.gy)), w: 0, h: 0 };
      const mode = (dy < 0 ? 'n' : 's') + (dx < 0 ? 'w' : 'e');
      setRect(resizeRect(anchor, mode, dx, dy));
    } else {
      setRect(resizeRect(drag.start, drag.mode, dx, dy));
    }
  }, { signal });

  const end = () => {
    drag = null;
    canvas.style.cursor = '';
  };
  canvas.addEventListener('pointerup', end, { signal });
  canvas.addEventListener('pointercancel', end, { signal });

  const offLayout = player.on('layout', draw);
  cleanup = () => {
    controller.abort();
    offLayout();
  };
  requestAnimationFrame(draw);
}

function draw() {
  const canvas = document.getElementById('crop-canvas');
  if (canvas.classList.contains('hidden')) return;
  const wrap = player.getMediaWrap();
  const s = player.getScale();
  const cssW = wrap.clientWidth + PAD * 2;
  const cssH = wrap.clientHeight + PAD * 2;
  const dpr = window.devicePixelRatio || 1;
  if (canvas.width !== Math.round(cssW * dpr) || canvas.height !== Math.round(cssH * dpr)) {
    canvas.width = Math.round(cssW * dpr);
    canvas.height = Math.round(cssH * dpr);
  }

  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, cssW, cssH);

  const l = PAD + rect.x * s, t = PAD + rect.y * s;
  const w = rect.w * s, h = rect.h * s;
  const accent = '#f59e0b';

  // Dim everything outside the crop box (only over the GIF itself)
  ctx.fillStyle = 'rgba(15, 10, 30, 0.55)';
  ctx.beginPath();
  ctx.rect(PAD, PAD, wrap.clientWidth, wrap.clientHeight);
  ctx.rect(l, t, w, h);
  ctx.fill('evenodd');

  // Rule-of-thirds grid
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.45)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 1; i < 3; i++) {
    ctx.moveTo(l + (w * i) / 3, t); ctx.lineTo(l + (w * i) / 3, t + h);
    ctx.moveTo(l, t + (h * i) / 3); ctx.lineTo(l + w, t + (h * i) / 3);
  }
  ctx.stroke();

  // Border
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2;
  ctx.strokeRect(l, t, w, h);

  // Corner handles (round) and edge handles (pills)
  ctx.fillStyle = '#ffffff';
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2.5;
  for (const [hx, hy] of [[l, t], [l + w, t], [l, t + h], [l + w, t + h]]) {
    ctx.beginPath();
    ctx.arc(hx, hy, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }
  const pill = (x, y, horizontal) => {
    ctx.beginPath();
    ctx.roundRect(horizontal ? x - 9 : x - 3, horizontal ? y - 3 : y - 9, horizontal ? 18 : 6, horizontal ? 6 : 18, 3);
    ctx.fill();
    ctx.stroke();
  };
  if (w > 40) { pill(l + w / 2, t, true); pill(l + w / 2, t + h, true); }
  if (h > 40) { pill(l, t + h / 2, false); pill(l + w, t + h / 2, false); }

  // Size label
  const label = `${rect.w} × ${rect.h}`;
  ctx.font = '700 12px "Nunito Variable", system-ui, sans-serif';
  const tw = ctx.measureText(label).width + 12;
  const ly = t + h + 26 < cssH ? t + h + 8 : t + 8;
  ctx.fillStyle = accent;
  ctx.beginPath();
  ctx.roundRect(l + w / 2 - tw / 2, ly, tw, 18, 9);
  ctx.fill();
  ctx.fillStyle = '#1f1a2e';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(label, l + w / 2, ly + 9.5);
}

import { getState } from '../utils/state.js';
import { trimCmd } from '../ffmpeg/commands.js';
import { showToast } from '../components/toast.js';
import { formatSize } from '../utils/file-utils.js';
import { registerTool } from '../components/toolbar.js';
import { applyEdit } from './shared.js';
import * as player from '../components/player.js';
import { panelHeader, button, note } from '../ui/components.js';

const tool = {
  id: 'trim',
  label: 'Trim',
  iconName: 'trim',
  hue: 'rose',
  hint: 'Keep just the best part.',
  render: renderTrim,
  exit: exitTrim,
};
registerTool(tool);

/** Half the handle width: the range thumbs are inset by this much at both ends */
const THUMB_HALF = 8;

let cleanup = null;

function exitTrim() {
  cleanup?.();
  cleanup = null;
  player.setLoopRange(null);
}

/** Cumulative start time (ms) of each frame boundary 0..n */
function boundaries(delays) {
  const cum = [0];
  for (const d of delays) cum.push(cum[cum.length - 1] + (d || 100));
  return cum;
}

const secs = (ms) => `${(ms / 1000).toFixed(2)}s`;

function renderTrim(panel) {
  const { meta } = getState();
  const n = meta.frames;
  const cum = boundaries(meta.delays.length === n ? meta.delays : Array(n).fill(meta.duration / n || 100));

  panel.innerHTML = `
    ${panelHeader(tool)}
    <div class="space-y-4" data-hue="rose">
      <div class="relative h-16 select-none" id="trim-track">
        <div class="absolute inset-y-0 rounded-xl overflow-hidden bg-surface-2" style="left:${THUMB_HALF}px;right:${THUMB_HALF}px">
          <canvas id="trim-strip" class="w-full h-full block"></canvas>
          <div id="trim-dim-l" class="absolute inset-y-0 left-0 bg-canvas/75"></div>
          <div id="trim-dim-r" class="absolute inset-y-0 right-0 bg-canvas/75"></div>
          <div id="trim-playhead" class="absolute inset-y-0 w-0.5 bg-ink/80 pointer-events-none"></div>
        </div>
        <input id="trim-start" type="range" class="dual-range" min="0" max="${n}" step="1" value="0" aria-label="Start frame" />
        <input id="trim-end" type="range" class="dual-range" min="0" max="${n}" step="1" value="${n}" aria-label="End frame" />
      </div>
      <div class="grid grid-cols-3 gap-2 text-center">
        <div class="rounded-2xl bg-surface-2 p-2"><p class="text-xs font-bold text-muted">Start</p><p id="trim-start-label" class="font-extrabold tabular-nums"></p></div>
        <div class="rounded-2xl bg-surface-2 p-2"><p class="text-xs font-bold text-muted">End</p><p id="trim-end-label" class="font-extrabold tabular-nums"></p></div>
        <div class="rounded-2xl hue-chip p-2"><p class="text-xs font-bold opacity-80">Keeps</p><p id="trim-len-label" class="font-extrabold tabular-nums"></p></div>
      </div>
      ${button({ id: 'trim-apply', label: 'Apply trim', iconName: 'check', variant: 'primary', block: true })}
      ${player.isFrameAccurate()
        ? note('The preview loops your selection. Handles snap to frames.')
        : note('Live loop preview isn’t available in this browser. The handles still snap to frames.')}
    </div>
  `;

  const startInput = document.getElementById('trim-start');
  const endInput = document.getElementById('trim-end');
  const pct = (v) => `${(v / n) * 100}%`;

  const update = (changed) => {
    let s = parseInt(startInput.value, 10);
    let e = parseInt(endInput.value, 10);
    // Keep at least one frame selected
    if (e - s < 1) {
      if (changed === startInput) s = startInput.value = e - 1;
      else e = endInput.value = s + 1;
    }
    document.getElementById('trim-dim-l').style.width = pct(s);
    document.getElementById('trim-dim-r').style.width = pct(n - e);
    document.getElementById('trim-start-label').textContent = `#${s + 1} · ${secs(cum[s])}`;
    document.getElementById('trim-end-label').textContent = `#${e} · ${secs(cum[e])}`;
    document.getElementById('trim-len-label').textContent = `${e - s} fr · ${secs(cum[e] - cum[s])}`;
    player.setLoopRange([s, e]);
    if (changed) player.seek(changed === endInput ? e - 1 : s);
  };

  startInput.addEventListener('input', () => update(startInput));
  endInput.addEventListener('input', () => update(endInput));
  update(null);

  // Filmstrip thumbnails (once frames are decoded) and a playhead
  const strip = document.getElementById('trim-strip');
  let stripDone = drawStrip(strip, n, meta);
  const offFrame = player.on('frame', () => {
    if (!stripDone) stripDone = drawStrip(strip, n, meta);
    const { index } = player.getFrameInfo();
    document.getElementById('trim-playhead').style.left = `${((index + 0.5) / n) * 100}%`;
  });
  cleanup = offFrame;

  document.getElementById('trim-apply').addEventListener('click', () => {
    const s = parseInt(startInput.value, 10);
    const e = parseInt(endInput.value, 10);
    if (s === 0 && e === n) { showToast('Drag the handles to choose what to keep', 'info'); return; }

    // Nudge the cut points half a millisecond inside so FFmpeg's timestamp
    // comparisons land cleanly on frame boundaries
    const start = s > 0 ? Math.max(0, cum[s] / 1000 - 0.0005) : 0;
    const duration = (cum[e] - cum[s]) / 1000 - 0.0005;

    applyEdit({
      label: `Trim to ${e - s} frames`,
      busy: 'Trimming…',
      passes: [trimCmd('input.gif', 'output.gif', Number(start.toFixed(4)), Number(duration.toFixed(4)))],
      success: (result) => `Trimmed to ${secs(cum[e] - cum[s])} (${formatSize(result.byteLength)})`,
    });
  });
}

/** Tile frame thumbnails across the strip; returns true once real thumbnails were drawn */
function drawStrip(canvas, n, meta) {
  const cssW = canvas.clientWidth;
  const cssH = canvas.clientHeight;
  if (!cssW || !cssH) return false;
  const dpr = window.devicePixelRatio || 1;
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const haveFrames = player.isFrameAccurate() && player.getBitmap(n - 1) !== null;
  if (!haveFrames) {
    // Placeholder: one alternating stripe per frame
    const w = cssW / n;
    for (let i = 0; i < n; i++) {
      ctx.fillStyle = i % 2 ? 'rgba(244, 63, 94, 0.22)' : 'rgba(244, 63, 94, 0.12)';
      ctx.fillRect(i * w, 0, Math.ceil(w), cssH);
    }
    return false;
  }

  const tileW = Math.max(24, cssH * (meta.width / meta.height));
  const tiles = Math.ceil(cssW / tileW);
  for (let k = 0; k < tiles; k++) {
    const frame = Math.min(n - 1, Math.floor(((k + 0.5) * tileW / cssW) * n));
    const bmp = player.getBitmap(frame);
    if (!bmp) continue;
    // Cover-fit the frame into the tile
    const s = Math.max(tileW / bmp.width, cssH / bmp.height);
    const sw = tileW / s, sh = cssH / s;
    ctx.drawImage(bmp, (bmp.width - sw) / 2, (bmp.height - sh) / 2, sw, sh, k * tileW, 0, tileW, cssH);
  }
  return true;
}

