import struct, sys, math

def lzw_encode(indices, min_code_size):
    clear = 1 << min_code_size
    eoi = clear + 1
    out_bits = []
    code_size = min_code_size + 1
    table = {bytes([i]): i for i in range(clear)}
    next_code = eoi + 1
    bitbuf = 0; bitlen = 0; out = bytearray()
    def emit(code):
        nonlocal bitbuf, bitlen
        bitbuf |= code << bitlen; bitlen += code_size
        while bitlen >= 8:
            out.append(bitbuf & 0xff); bitbuf >>= 8; bitlen -= 8
    emit(clear)
    w = b''
    for idx in indices:
        c = bytes([idx]); wc = w + c
        if wc in table:
            w = wc
        else:
            emit(table[w])
            if next_code < 4096:
                table[wc] = next_code; next_code += 1
                if next_code > (1 << code_size) and code_size < 12:
                    code_size += 1
            else:
                emit(clear)
                table = {bytes([i]): i for i in range(clear)}
                next_code = eoi + 1; code_size = min_code_size + 1
            w = c
    if w: emit(table[w])
    emit(eoi)
    if bitlen: out.append(bitbuf & 0xff)
    return bytes(out)

def make(path, W, H, nframes, delay_cs):
    palette = [(255,255,255),(124,58,237),(236,72,153),(245,158,11),(16,185,129),(14,165,233),(31,26,46),(250,204,21)]
    pal = b''.join(bytes(c) for c in palette)
    data = bytearray(b'GIF89a')
    data += struct.pack('<HHBBB', W, H, 0xF2, 0, 0)  # GCT, 8 colors
    data += pal
    data += b'\x21\xff\x0bNETSCAPE2.0\x03\x01\x00\x00\x00'
    for f in range(nframes):
        t = f / nframes
        cx = int((W - 16) * (0.5 + 0.45 * math.sin(2 * math.pi * t)))
        cy = int((H - 16) * (0.5 + 0.45 * math.cos(2 * math.pi * t)))
        px = []
        for y in range(H):
            for x in range(W):
                if cx <= x < cx + 16 and cy <= y < cy + 16: px.append(1 + f % 5)
                elif (x // 8 + y // 8) % 2 == 0: px.append(0)
                else: px.append(7 if y < H // 2 else 6)
        data += b'\x21\xf9\x04\x04' + struct.pack('<H', delay_cs) + b'\x00\x00'
        data += b'\x2c' + struct.pack('<HHHHB', 0, 0, W, H, 0)
        data += b'\x02'
        enc = lzw_encode(px, 2 if False else 3)[:]
        data[-1:] = b'\x03'
        for i in range(0, len(enc), 255):
            chunk = enc[i:i+255]; data += bytes([len(chunk)]) + chunk
        data += b'\x00'
    data += b'\x3b'
    open(path, 'wb').write(data)

make(sys.argv[1], int(sys.argv[2]), int(sys.argv[3]), int(sys.argv[4]), int(sys.argv[5]))
EOF
